def page(file,title,body,active=None,cta=True):
 if file=='proyectos.html':
  filters='<nav class="project-filters" aria-label="Filtrar proyectos"><a href="#todos" data-filter="todos">Todos</a><a href="#ux" data-filter="ux">UX</a><a href="#ui" data-filter="ui">UI</a><a href="#diseno-grafico" data-filter="diseno-grafico">Diseño gráfico</a></nav><p class="filter-status" role="status" aria-live="polite"></p>'
  body=body.replace('<div class="cards">',filters+'<div class="cards">',1)
 (d/file).write_text(f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Susana Tralma</title><meta name="description" content="Susana Tralma, diseñadora UX/UI y gráfica enfocada en software, SaaS B2B y tecnología. Explora sus proyectos y proceso de diseño."><meta name="theme-color" content="#F4F4F4"><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#contenido">Saltar al contenido</a>{{{{SITE_HEADER}}}}<main id="contenido">{body}</main><footer><div class="wrap"><span>Hecho por Susana Tralma © 2026</span><span>Diseño gráfico · UX/UI · Sistemas de diseño</span></div></footer><script src="script.js"></script></body></html>''')
projects=[('regcheq','Regcheq','SaaS B2B · Sistema de diseño','Una base visual compartida entre diseño y desarrollo.','inicio-2'),('komatsu','Komatsu','Minería · Evaluación UX','Hacer más clara la navegación de un producto complejo.','inicio-1'),('cademsmart','Cademsmart','Retail · Experiencia móvil','De dispositivos industriales a una interfaz Android.','inicio-3')]
