projects.append(('essana','Clínica Essana','2025 · Proyecto académico · Diseño gráfico','Manual de Marca e identidad Corporativa','essana-hero'))
projects.append(('essana-web','Clínica Essana · Web y app','2025 · Proyecto conceptual · UI','Tu bienestar evoluciona','essana-web-cover'))
def cards():return '<div class="cards">'+''.join(f'<a class="card" data-disciplines="{'diseno-grafico' if slug == 'essana' else 'ui' if slug == 'essana-web' else 'ux ui'}" href="{slug}.html"><div class="photo"><img src="assets/{im}.webp" alt="{'Portada del proyecto' if slug in {'claro','essana','essana-web'} else 'Portada conceptual de'} {name}" loading="lazy"></div><div class="meta">{meta}</div><h3>{name}<span class="arrow" aria-hidden="true">↗</span></h3><p>{desc}</p><span class="case-link">Explorar caso <span aria-hidden="true">→</span></span></a>' for slug,name,meta,desc,im in projects)+'</div>'
page('index.html','Diseño UX/UI y gráfico para tecnología','''<section class="hero homehero"><div class="wrap"><div class="editorial-kicker"><span>Diseño UX/UI + Diseño gráfico</span><span>Portafolio / 2026</span></div><h1>Portafolio creativo.</h1><div class="hero-editorial-copy"><p>Soy Susana Tralma. Diseño experiencias e interfaces para que la tecnología sea más clara, útil y cercana.</p><p class="muted">Mi enfoque combina diseño gráfico y UX/UI para productos de software y SaaS.</p><div class="actions"><a class="btn" href="#seleccion">Explorar proyectos <span aria-hidden="true">↘</span></a></div></div><div class="editorial-meta"><span><b aria-hidden="true">●</b> Susana Tralma</span><span>Diseñadora UX/UI + Gráfica</span><span>Software · SaaS · Tecnología</span><a class="textlink" href="contacto.html">Conversemos ↗</a></div></div></section><section class="section introduction"><div class="wrap"><div class="editorial-kicker"><span>Una mirada, dos disciplinas</span><span>01 / Presentación</span></div><div class="intro-grid"><div><h2>Hola, soy<br>Susana<br>Tralma.</h2><p>Me gusta crear. También entender qué estamos resolviendo. Conecto estructura, identidad visual e interacción para hacer más comprensibles los productos digitales.</p><a class="textlink" href="sobre-mi.html">Conoce mi enfoque ↗</a></div><figure class="intro-visual"><img src="assets/regcheq-53.webp" alt="Fundamentos visuales del sistema de diseño de Regcheq" loading="lazy"><figcaption>De la idea al sistema. Extracto de mi trabajo en Regcheq.</figcaption></figure></div></div></section><section class="section work-section" id="seleccion"><div class="wrap"><div class="section-head"><div><p class="eyebrow">02 / Trabajo seleccionado</p><h2>Del desafío a la interfaz.</h2></div><p class="muted section-intro">Tres contextos distintos.<br>Una misma búsqueda de claridad.</p></div>'''+cards()+'''<p class="asset-note">Las portadas son imágenes conceptuales generadas con IA. En cada caso identifico los entregables y las referencias.</p></div></section><section class="section approach"><div class="wrap"><div class="section-head"><div><p class="eyebrow">03 / Dos disciplinas, una mirada</p><h2>Que funcione bien.<br>Que también se sienta bien.</h2></div><p class="section-intro">Mi base gráfica aporta jerarquía y carácter. Mi práctica UX/UI organiza la experiencia alrededor de las personas.</p></div><div class="expertise-grid"><article><span class="step">01</span><h3>Entender para simplificar</h3><p>Investigar el contexto, recorrer flujos y reconocer dónde una interfaz exige demasiado a quien la usa.</p><span class="expertise-label">Experiencia de usuario</span></article><article><span class="step">02</span><h3>Dar forma a la claridad</h3><p>Usar tipografía, composición y color para que la información se entienda y cada acción tenga su lugar.</p><span class="expertise-label">Diseño gráfico + UI</span></article><article><span class="step">03</span><h3>Conectar las piezas</h3><p>Construir componentes y documentar decisiones para dar coherencia al producto y colaborar con desarrollo.</p><span class="expertise-label">Sistemas de diseño</span></article></div></div></section><section class="section about-preview"><div class="wrap split"><div><p class="eyebrow">04 / Detrás del diseño</p><h2>Observar con curiosidad.<br>Diseñar con intención.</h2></div><div><p>Me interesan los productos donde hay mucho por ordenar y personas que necesitan avanzar con confianza. Disfruto conectar el detalle visual con la lógica de una experiencia.</p><a class="textlink" href="sobre-mi.html">Más sobre mí y mi forma de trabajar ↗</a></div></div></section>''')
page('proyectos.html','Proyectos','''<section class="hero"><div class="wrap"><div class="eyebrow">Portafolio / Trabajo seleccionado</div><h1>Decisiones de diseño.<br><span class="blue">Contextos reales.</span></h1><p class="sub">Proyectos de sistemas de diseño, evaluación de usabilidad y experiencias móviles.</p></div></section><section class="section"><div class="wrap">'''+cards()+'''</div></section>''')
page('sobre-mi.html','Sobre mí','''<section class="hero"><div class="wrap"><div class="eyebrow">Sobre mí</div><h1>Curiosa al explorar.<br><span class="blue">Rigurosa al diseñar.</span></h1><p class="sub">Soy Susana Tralma, diseñadora UX/UI y diseñadora gráfica enfocada en software, SaaS y tecnología. Conecto la lógica de una experiencia con la sensibilidad visual para hacer más claros los productos digitales.</p></div></section><section class="section"><div class="wrap split"><div><h2>Diseño, aprendizaje y colaboración.</h2><p>No solo me interesa colaborar en proyectos: también conocer y compartir perspectivas sobre negocios y diseño.</p><p class="muted">Mi trabajo reúne análisis de interfaces, organización de información y construcción de sistemas visuales. Exploro herramientas de inteligencia artificial como apoyo al proceso, con revisión y criterio de diseño.</p></div><div class="statement"><span class="mark">ST.</span><p>Creativa, observadora y cercana.</p></div></div></section><section class="section gray"><div class="wrap split"><div><div class="eyebrow">Formación</div><h2>Mis estudios</h2><p>Diseño Gráfico profesional</p><p>Certificación UX/UI</p></div><div><div class="eyebrow">Forma de trabajar</div><h2>Habilidades</h2><div class="skills">'''+''.join(f'<span class="tag">{x}</span>' for x in ['Pensamiento crítico','Planificación','Autonomía','Colaboración','Empatía','Aprendizaje continuo'])+'''</div></div></div></section><section class="section"><div class="wrap"><h2>Herramientas y exploración</h2><p class="muted">Herramientas que forman parte de mi práctica y aprendizaje.</p><div class="skills">'''+''.join(f'<span class="tag">{x}</span>' for x in ['Figma','FigJam','Claude Code','HTML / CSS','VS Code','Photoshop','Illustrator','Maze','Optimal Workshop','Antigravity'])+'''</div></div></section>''')
page('contacto.html','Contacto','''<section class="hero contact-page"><div class="wrap"><h1>¿Trabajamos juntos?</h1><p>Escríbeme directamente a <a href="mailto:susanauxd@gmail.com">susanauxd@gmail.com</a> o agendemos una llamada.</p><a class="pill calendly-action" href="https://calendly.com/susanauxd/30min?month=2026-11" target="_blank" rel="noopener noreferrer">Agenda una reunión de 15 minutos en mi Calendly</a></div></section>''',cta=False)
page('blog.html','Blog','''<section class="hero"><div class="wrap"><div class="eyebrow">Blog / Diseño y negocios</div><h1>Ideas para hacer<br><span class="blue">más claro lo complejo.</span></h1><p class="sub">Un espacio para compartir aprendizajes sobre UX/UI, sistemas de diseño y la relación entre las personas, la tecnología y el negocio.</p></div></section><section class="section"><div class="wrap"><div class="section-head"><h2>En preparación</h2><span class="small muted">Propuestas editoriales</span></div><div class="article-list">'''+''.join(f'<details class="article"><summary>{t}</summary><p class="eyebrow" style="margin-top:24px">Artículo en preparación</p><p class="muted">{p}</p></details>' for t,p in [('Cómo hacer más claro lo complejo: interfaces B2B','Una propuesta sobre cómo estructurar información densa, priorizar decisiones operativas y convertir hallazgos en mejoras visuales. El artículo completo aún no está publicado.'),('Cómo priorizar decisiones operativas','Una propuesta para explorar cómo ordenar acciones, estados y mensajes para que las personas puedan tomar decisiones con claridad. El artículo completo aún no está publicado.'),('Tokens, documentación y colaboración con Front-End','Una propuesta sobre cómo alinear diseño y código para que un sistema de diseño sea útil y fácil de mantener. El artículo completo aún no está publicado.')])+'''</div></div></section>''')
def fig(src,caption):return f'<figure><img src="assets/{src}.webp" alt="{html.escape(caption)}" loading="lazy"><figcaption>{caption}</figcaption></figure>'
def case(slug,name,title,intro,role,platform,focus,sections):
 body=f'<section class="hero casehero"><div class="wrap"><a class="breadcrumb" href="proyectos.html">← Volver a proyectos</a><div class="eyebrow" style="margin-top:32px">{name}</div><h1>{title}</h1><p class="sub">{intro}</p><dl class="facts"><div><dt>Rol</dt><dd>{role}</dd></div><div><dt>Plataforma</dt><dd>{platform}</dd></div><div><dt>Enfoque</dt><dd>{focus}</dd></div></dl></div></section><div class="wrap case-layout"><aside class="toc" aria-label="Contenido del caso"><span class="eyebrow">En este proyecto</span>'+''.join(f'<a href="#s{i}">{t}</a>' for i,(t,c) in enumerate(sections))+'</aside><div class="casebody">'+''.join(f'<section id="s{i}"><div class="eyebrow">0{i+1} / {name}</div><h2>{t}</h2>{c}</section>' for i,(t,c) in enumerate(sections))+'<a class="textlink" href="proyectos.html">← Explorar otros proyectos</a></div></div>'
 page(slug+'.html',name,body,'proyectos.html')
case('regcheq','Regcheq','Una base para un sistema<br>de diseño B2B.','Refactorización del UI Kit y construcción de fundamentos visuales para una plataforma SaaS de compliance.','Diseñadora UX/UI · Práctica','Web B2B','Sistema de diseño · UI · Handoff',[
('Contexto y desafío','<p>Regcheq es una plataforma SaaS B2B de compliance. El proyecto abordó una interfaz fragmentada y la necesidad de crear un estándar visual compartido con Front-End.</p><p>El objetivo fue reorganizar el UI Kit, definir fundamentos y componentes y preparar una base para la continuidad del sistema.</p>'),
('Fundamentos y componentes','<p>La alineación con el ecosistema React y shadcn orientó la nomenclatura de componentes y tokens.</p><h3>De decisiones aisladas a una base común</h3><ul><li>Definición de estilos de color, tipografía, espaciado y radios.</li><li>Uso de Inter para interfaces con alta densidad de información.</li><li>Construcción de botones, formularios, tablas, diálogos y estados.</li><li>Organización de variables y documentación en Figma.</li></ul>'+fig('regcheq-32','Extracto de variables y tokens configurados en Figma.')+fig('regcheq-53','Extracto de los fundamentos visuales del sistema en Figma.')),
('Diseño asistido por IA','<p>Se utilizó Claude como apoyo para estructurar componentes, revisar nomenclaturas y documentar decisiones. La revisión humana formó parte del proceso.</p><p>La documentación en Figma y ClickUp buscó facilitar el traspaso y la continuidad del trabajo.</p>'),
('Aplicación en interfaces','<p>Los componentes se aplicaron a propuestas de interfaz y flujos de monitoreo. El trabajo se apoyó en conversaciones y sesiones con Producto, Comercial y Customer Experience.</p><div class="compare">'+fig('regcheq-20','Antes: interfaz basada en el UI Kit.')+fig('regcheq-39','Después: propuesta con componentes del sistema de diseño.')+'</div><div class="compare">'+fig('regcheq-50','Antes: formulario de expediente.')+fig('regcheq-6','Después: propuesta de formulario con componentes unificados.')+'</div><div class="note">Se ocultan datos para resguardar información del producto. Por plazos de entrega, no se realizaron pruebas de usabilidad con usuarios finales antes del cierre de la práctica.</div>'),
('Entrega y aprendizajes','<p>La entrega incluyó la biblioteca base, fundamentos, documentación y prototipos para apoyar la continuidad con diseño y desarrollo.</p><h3>Lo que me llevo</h3><ul><li>Comprender el stack ayuda a tomar decisiones de diseño más compatibles con desarrollo.</li><li>Un sistema necesita documentación y acuerdos, además de componentes.</li><li>La IA aporta velocidad; el criterio y la validación siguen siendo necesarios.</li></ul>')])
case('komatsu','Komatsu Cummins Chile · 2024','Evaluación de una<br>interfaz minera.','Evaluación heurística y propuestas de mejora visual y estructural para una plataforma SaaS B2B orientada a la productividad y eficiencia de maquinaria minera.','Diseñadora UX/UI en práctica','Web B2B','Arquitectura de información · Usabilidad',[
('Contexto','<p>Komatsu Cummins Chile pertenece al sector de maquinaria para la minería y utiliza plataformas digitales para apoyar la productividad y eficiencia de su maquinaria.</p><p>El proyecto se desarrolló en 2024 sobre una plataforma de trabajo con múltiples pantallas, información operacional y términos especializados. El objetivo fue identificar problemas de navegación, jerarquía y consistencia para proponer mejoras.</p><h3>Mis responsabilidades</h3><ul><li>Realizar una evaluación heurística completa.</li><li>Proponer mejoras visuales y estructurales.</li><li>Participar en workshops de alineación.</li></ul>'),
('Investigación previa','<p>Comencé recopilando información existente de la empresa, revisando las herramientas utilizadas y buscando buenas prácticas de UX/UI para contextualizar la evaluación.</p><h3>Materiales y referencias revisadas</h3><ul><li><strong>Manual de marca y UI Kit:</strong> revisión de los recursos visuales existentes.</li><li><strong>Material Design:</strong> documentación de buenas prácticas de gráficos.</li><li><strong>amCharts:</strong> revisión del sistema de gráficos utilizado en la plataforma.</li><li><strong>Google Charts:</strong> referencia de visualización de datos.</li><li><strong>Nielsen Norman Group:</strong> documentación de heurísticas de usabilidad.</li><li><strong>Interaction Design Foundation:</strong> documentación de diseño de interacción.</li><li><strong>Análisis de otras plataformas:</strong> material de comparación e inspiración.</li></ul>'+fig('komatsu-investigacion','Recopilación de materiales y referencias de la investigación previa, extraída del documento del proyecto.')),
('Arquitectura y flujos','<p>Representé los menús, categorías y páginas para dimensionar la profundidad del producto y organizar la evaluación.</p><h3>Mapa de sitio</h3><p>El mapa permitió dimensionar las áreas profundas, contabilizar páginas por categoría y comprender la complejidad del producto. Se analizaron más de 50 páginas.</p><h3>Wireflow</h3><p>Agrupé visualmente los elementos repetidos para revisar los flujos de usuario y la consistencia de la interfaz. Esto ayudó a detectar problemas de jerarquía, duplicación y navegación confusa, además de organizar tareas y tiempos de ejecución de la evaluación.</p>'+fig('komatsu-11','Mapa de sitio referencial; se ocultan datos del producto.')+fig('komatsu-6','Agrupación visual de pantallas y flujos; datos ocultos.')),
('Evaluación heurística','<p>La revisión se apoyó en las heurísticas de Nielsen. Los incumplimientos más destacados correspondieron a:</p><ul><li><strong>Heurística 1 · Visibilidad del estado del sistema:</strong> faltaban pistas visuales que informaran al usuario sobre lo que ocurría.</li><li><strong>Heurística 6 · Reconocimiento antes que recuerdo:</strong> la interfaz no facilitaba suficientemente reconocer la información, lo que aumentaba la carga cognitiva al realizar tareas.</li></ul>'+fig('komatsu-1','Extracto de la tabla de evaluación heurística.')+fig('komatsu-5','Criterios de evaluación y clasificación de hallazgos.')),
('Propuestas de mejora','<p>Se propusieron ajustes de jerarquía y agrupación para ofrecer pistas visuales más claras.</p><h3>Ranking de operadores</h3><p>Se propuso mostrar grupos de diez operadores por página, ordenados de mayor a menor. En el escenario documentado, el paginador pasaría de 52 a 12 páginas.</p><p>También se identificó que la barra de índice de efectividad estaba asociada al porcentaje del ranking. Se propuso incorporar ese porcentaje en la barra de progreso para hacer explícita la relación y reducir el ancho de la tarjeta.</p><div class="compare">'+fig('komatsu-7','Vista anterior: referencia con datos ocultos.')+fig('komatsu-10','Propuesta visual: referencia con datos ocultos.')+'</div>'+'<div class="compare">'+fig('komatsu-3','Antes: ranking de operadores en tarjetas.')+fig('komatsu-0','Propuesta: ranking agrupado en una tabla.')+'</div>'+'<div class="note">Son propuestas de diseño. No se presentan mejoras de rendimiento o usabilidad como resultados medidos.</div>'),
('Aprendizajes','<ul><li>Organizar un producto complejo antes de evaluar facilita el análisis.</li><li>Los hallazgos necesitan traducirse en propuestas concretas y priorizables.</li><li>La visualización de datos debe acompañar las tareas y el lenguaje del usuario.</li><li>La comunicación con equipos multidisciplinarios ayuda a alinear las mejoras.</li><li>El trabajo con alta autonomía fortaleció mis habilidades de arquitectura de información, análisis heurístico y diseño visual.</li><li>Profundicé en el lenguaje y los términos de minería e ingeniería.</li><li>Las propuestas quedaron preparadas para implementación o validación con usuarios.</li></ul>')])
case('cademsmart','Cademsmart','Del dispositivo industrial<br>a una experiencia móvil.','Migración de plataforma y rediseño de interfaz para la captura de datos de auditores en puntos de venta.','Diseñadora UX/UI','Android móvil','Investigación de campo · Flujos · UI',[
('Contexto','<p>El desafío consistió en adaptar una aplicación utilizada en dispositivos industriales Zebra a teléfonos Android. El cambio requería repensar interacciones táctiles, flujos de captura y funcionalidades operativas.</p><p>El contexto de uso —auditores en supermercados— fue central para comprender las necesidades del producto.</p>'+fig('cademsmart-6','Referencia del tipo de dispositivo industrial utilizado en terreno.')),
('Investigación y flujos','<p>El análisis de la aplicación existente se complementó con observación y entrevistas en salas de venta, para comprender cómo se registraban y enviaban los datos.</p><ul><li>Feedback visual, sonoro y por vibración para confirmar acciones.</li><li>Visibilidad del estado de sincronización.</li><li>Organización de visitas y tareas del día.</li></ul>'+fig('cademsmart-5','Representación referencial del flujo, elaborada en FigJam.')+fig('cademsmart-7','Imagen referencial generada con IA para ilustrar el contexto de auditoría en terreno.')),
('Decisiones de diseño','<h3>Considerar la conectividad</h3><p>El diseño contempló estados de guardado local y sincronización pendiente, buscando que la persona comprendiera qué había ocurrido con sus datos.</p><h3>Organizar la jornada</h3><p>La propuesta de inicio agrupó visitas y tareas para ayudar al auditor a reconocer su trabajo pendiente.</p><h3>Explorar antes de detallar</h3><p>Los bocetos de baja fidelidad permitieron explorar la distribución de información antes de avanzar a pantallas de mayor fidelidad.</p>'),
('Validación y entrega','<p>El caso describe revisiones cualitativas con equipo interno y auditores, enfocadas en reconocimiento de elementos, realización de tareas y adaptación a la nueva interfaz.</p><p>Los prototipos finales se presentaron a las áreas Comercial y TI para orientar la implementación.</p>'+fig('cademsmart-1','Representación conceptual generada con IA; no corresponde a una captura del prototipo original.')+'<div class="note">Las imágenes conceptuales ilustran el contexto y el formato del trabajo. No se presentan como evidencia de pruebas ni como interfaces originales de la empresa.</div>'),
('Aprendizajes','<p>Diseñar para el trabajo en terreno exige observar lo que ocurre más allá de la pantalla: conectividad, atención disponible, condiciones del entorno y hábitos adquiridos.</p><p>Una migración tecnológica también implica acompañar un cambio en la manera de trabajar.</p>')])
